mapper.select:
SELECT c.id, c.is_in_progress, c.name, c.number_of_learner, c.start_date, c.end_date, c.total_hours, c.total_days, c.daily_hours, c.break_time, c.lesson_start_time, c.lesson_end_time, c.lunch_start_time, c.lunch_end_time, c.created_at, c.updated_at, c.deleted_at FROM course c
INNER JOIN learner_enrollment le ON c.id = le.course_id
LEFT JOIN staff_assignment sa ON c.id = sa.course_id LEFT JOIN user u ON sa.user_id = u.id
ORDER BY ${pageCourseReqDTO.orderBy} ${pageCourseReqDTO.orderDirection}
LIMIT #{pageCourseReqDTO.offset}, #{pageCourseReqDTO.pageSize}

SELECT c.id, c.is_in_progress, c.name, c.number_of_learner, c.start_date, c.end_date, c.total_hours, c.total_days, c.daily_hours, c.break_time, c.lesson_start_time, c.lesson_end_time, c.lunch_start_time, c.lunch_end_time, c.created_at, c.updated_at, c.deleted_at FROM course c
INNER JOIN learner_enrollment le ON c.id = le.course_id
LEFT JOIN staff_assignment sa ON c.id = sa.course_id LEFT JOIN user u ON sa.user_id = u.id
c.id = #{courseId}
AND le.user_id = #{loginUserId}
AND sa.user_id = #{loginUserId}

SELECT u.id, u.type, u.fullname, u.mobile, le.completion_status FROM user u LEFT JOIN learner_enrollment le ON u.id = le.user_id WHERE type = 'LEARNER' AND u.id NOT IN ( SELECT u.id FROM user u LEFT JOIN learner_enrollment le ON u.id = le.user_id WHERE le.completion_status = 'IN_PROGRESS')
AND ${pageUserReqDTO.type} like concat('%', #{pageUserReqDTO.keyword}, '%')
AND le.completion_status IS NULL
ORDER BY ${pageUserReqDTO.orderBy} ${pageUserReqDTO.orderDirection}
LIMIT #{pageUserReqDTO.offset}, #{pageUserReqDTO.pageSize}

